mapper.select:
SELECT
COALESCE(
SUM(CASE WHEN transaction_type = 'INCOME' THEN amount ELSE 0 END),
0.00
) AS total_income,
COALESCE(
SUM(CASE WHEN transaction_type = 'EXPENSE' THEN amount ELSE 0 END),
0.00
) AS total_expense,
COUNT(*) AS bill_count
FROM bills
WHERE user_id = #{userId}
AND transaction_date >= #{startDate}
AND transaction_date < #{endDate}
